diff --git a/rust/fsl-core/tests/reviewgraphen_generated_calibration_10.rs b/rust/fsl-core/tests/reviewgraphen_generated_calibration_10.rs
new file mode 100644
--- /dev/null
+++ b/rust/fsl-core/tests/reviewgraphen_generated_calibration_10.rs
@@ -0,0 +1,19 @@
+// SPDX-License-Identifier: Apache-2.0
+
+use fsl_core::{FsResolver, build_model, parse_kernel_source};
+
+#[test]
+fn reviewgraphen_generated_regression() {
+    let source = r#"spec Invalid {
+  state { done: Bool }
+  init { done = false }
+  action apply(value: Missing) { }
+}"#;
+    let kernel = parse_kernel_source(source, &FsResolver::new("."))
+        .expect("the source should parse before semantic type resolution");
+    let error = build_model(kernel).expect_err("the unknown parameter type must be rejected");
+
+    assert!(error.message.contains("unknown type 'Missing'"));
+    let span = error.span.expect("the action error must retain its source span");
+    assert_eq!(span.start.line, 4);
+}
